function h(s,e,t){if(!s)return 0;let n=t*1e3,i=Math.min(Math.max(e,0),n);return Math.round(1e3*(1-i/n/2))}function M(s){let e=[0,0,0,0];for(let t of Object.values(s||{}))[0,1,2,3].includes(t&&t.choice)&&(e[t.choice]+=1);return e}function I({players:s={},answers:e={},reveals:t={}}){let n=new Map;for(let[i,o]of Object.entries(s))n.has(o.studentId)||n.set(o.studentId,{studentId:o.studentId,name:o.name,uids:[],total:0,correct:0,totalTime:0,perQ:{}}),n.get(o.studentId).uids.push(i);for(let[i,o]of Object.entries(t)){let d=e[i]||{};for(let c of n.values()){let l=c.uids.find(p=>d[p]);if(!l)continue;let r=d[l],m=o.timeLimit*1e3,u=Math.min(Math.max(r.at-o.startAt,0),m),a=r.choice===o.answer,f=h(a,u,o.timeLimit);c.perQ[i]={choice:r.choice,correct:a,elapsedMs:u,points:f},c.total+=f,a&&(c.correct+=1,c.totalTime+=u)}}return[...n.values()].map(({uids:i,...o})=>o)}function x(s){return[...s].sort((e,t)=>t.total-e.total||e.totalTime-t.totalTime||String(e.studentId).localeCompare(String(t.studentId))).map((e,t)=>({...e,rank:t+1}))}export{h as a,M as b,I as c,x as d};
